// Finds every file in src/pages/ automatically.
// To add a page you only create a new file there. You do NOT edit this file,
// App.jsx or the menu, so two people adding pages never clash.
//
// A page file looks like this (see src/pages/README in frontend/README.md):
//   export const path = '/my-page'      (optional, default comes from the file name)
//   export const title = 'My page'      (optional, shown in the menu)
//   export const order = 30             (optional, smaller = earlier in the menu)
//   export default function MyPage() { ... }

const modules = import.meta.glob('../pages/*.jsx', { eager: true })

function nameFromFile(file) {
  return file.split('/').pop().replace('.jsx', '').replace(/Page$/, '')
}

function kebab(name) {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()
}

function spaced(name) {
  return name.replace(/([a-z0-9])([A-Z])/g, '$1 $2')
}

export const pages = Object.entries(modules)
  .map(([file, mod]) => {
    const name = nameFromFile(file)
    return {
      Component: mod.default,
      path: mod.path ?? (name === 'Home' ? '/' : `/${kebab(name)}`),
      title: mod.title ?? spaced(name),
      order: mod.order ?? 100,
    }
  })
  .filter((p) => p.Component)
  .sort((a, b) => a.order - b.order || a.title.localeCompare(b.title))
